import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    events = []
    for _ in range(n):
        t = int(next(iterator))
        f = int(next(iterator))
        events.append((t, f))

    freq_time_groups = defaultdict(list)
    for t, f in events:
        freq_time_groups[f].append(t)

    max_needed = 0

    for f, times in freq_time_groups.items():
        if not times:
            continue

        needed = 1
        current_count = 1
        last_time = times[0]

        for i in range(1, len(times)):
            t_curr = times[i]
            t_prev = last_time

            if t_curr > t_prev:
                gap = t_curr - t_prev
                retune_time = abs(f - f)
                if gap < retune_time:
                    needed += 1
                    current_count = 1
                else:
                    current_count += 1
            else:
                current_count += 1

            last_time = t_curr

            if current_count > needed:
                needed = current_count

        if needed > max_needed:
            max_needed = needed

    print(max_needed)

if __name__ == "__main__":
    main()
